CREATE TABLE public.tme_schedule_period_revision_counters (
  period_revision_counter_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id BIGINT NOT NULL,
  public_id UUID NOT NULL DEFAULT pg_catalog.gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by UUID NOT NULL,
  period_code VARCHAR(100) NOT NULL,
  last_revision BIGINT NOT NULL,
  CONSTRAINT tme_schedule_period_revision_counters_u0 UNIQUE (tenant_id, period_code),
  CONSTRAINT tme_schedule_period_revision_counters_u1 UNIQUE (tenant_id, period_revision_counter_id),
  CONSTRAINT tme_schedule_period_revision_counters_u2 UNIQUE (tenant_id, public_id),
  CONSTRAINT tme_schedule_period_revision_counters_c0 CHECK (last_revision > 0)
);
ALTER TABLE public.tme_schedule_period_revision_counters ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.tme_schedule_period_revision_counters FORCE ROW LEVEL SECURITY;
CREATE POLICY tme_schedule_period_revision_counters_tenant_policy ON public.tme_schedule_period_revision_counters USING (tenant_id = NULLIF(current_setting('dwp.tenant_id', true), '')::BIGINT) WITH CHECK (tenant_id = NULLIF(current_setting('dwp.tenant_id', true), '')::BIGINT);

